package ai.eva.android.probe;
import java.io.*;import java.nio.charset.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import javax.xml.parsers.*;import org.w3c.dom.*;import org.xml.sax.InputSource;
/** Bounded, dependency-free offline OOXML content preview. Not an Office layout engine. */
final class DocumentPreview implements AutoCloseable {
 static final int ENTRY_LIMIT=4*1024*1024,TOTAL_LIMIT=20*1024*1024;final ZipFile zip;int readBytes,wordDepth;final Map<String,byte[]> cache=new HashMap<>();
 DocumentPreview(File f)throws IOException{if(f.length()>64L*1024*1024)throw new IOException("办公文件超过 64 MB 预览上限");zip=new ZipFile(f);if(zip.size()>20000){zip.close();throw new IOException("文档包含过多条目");}}
 public void close()throws IOException{zip.close();}
 static String ext(File f){String n=f.getName().toLowerCase(Locale.ROOT);return n.contains(".")?n.substring(n.lastIndexOf('.')+1):"";}
 static String kind(File f){String e=ext(f);if(Arrays.asList("docx","xlsx","pptx").contains(e))return "office";if(e.equals("svg"))return "svg";if(Arrays.asList("md","markdown").contains(e))return "markdown";if(Arrays.asList("html","htm").contains(e))return "html";if(Arrays.asList("mp3","m4a","wav","ogg","oga","aac","flac","opus").contains(e))return "audio";if(Arrays.asList("mp4","m4v","webm","mkv","3gp","mov").contains(e))return "video";if(Arrays.asList("txt","csv","tsv","json","xml","yaml","yml","log","py","js","css","java","kt","sh","ini","toml","sql").contains(e))return "text";return "unsupported";}
 static String mime(File f){String e=ext(f);switch(e){case "pdf":return "application/pdf";case "docx":return "application/vnd.openxmlformats-officedocument.wordprocessingml.document";case "xlsx":return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";case "pptx":return "application/vnd.openxmlformats-officedocument.presentationml.presentation";case "html":case "htm":return "text/html";case "md":case "markdown":return "text/markdown";case "mp4":case "m4v":return "video/mp4";case "webm":return "video/webm";case "mp3":return "audio/mpeg";case "m4a":return "audio/mp4";case "wav":return "audio/wav";case "ogg":case "oga":case "opus":return "audio/ogg";case "flac":return "audio/flac";case "png":return "image/png";case "jpg":case "jpeg":return "image/jpeg";case "webp":return "image/webp";case "gif":return "image/gif";default:return kind(f).equals("text")?"text/plain":"application/octet-stream";}}
 static String esc(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 static byte[] bounded(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("预览已取消");if(out.size()+n>max)throw new IOException("内容超出预览上限");out.write(b,0,n);}return out.toByteArray();}
 byte[] bytes(String path)throws IOException{if(path==null)return null;if(cache.containsKey(path))return cache.get(path);ZipEntry e=zip.getEntry(path);if(e==null)return null;if(e.getSize()>ENTRY_LIMIT)throw new IOException("文档内单项超过 4 MB");byte[] b;try(InputStream in=zip.getInputStream(e)){b=bounded(in,ENTRY_LIMIT);}readBytes+=b.length;if(readBytes>TOTAL_LIMIT)throw new IOException("文档解压内容超过 20 MB");cache.put(path,b);return b;}
 static String utf8(byte[] b)throws IOException{try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(b)).toString();}catch(CharacterCodingException e){throw new IOException("文件不是有效 UTF-8 文本");}}
 Document xml(String path)throws Exception{byte[] b=bytes(path);if(b==null)return null;String text=utf8(b);if(text.startsWith("\uFEFF"))text=text.substring(1);if(text.indexOf('\0')>=0||text.toUpperCase(Locale.ROOT).contains("<!DOCTYPE")||text.toUpperCase(Locale.ROOT).contains("<!ENTITY"))throw new IOException("文档包含不支持的 XML 实体或编码");DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);DocumentBuilder builder=f.newDocumentBuilder();builder.setEntityResolver((publicId,systemId)->new InputSource(new StringReader("")));return builder.parse(new InputSource(new StringReader(text)));}
 static List<Element> children(Node n){List<Element> out=new ArrayList<>();if(n!=null)for(Node c=n.getFirstChild();c!=null;c=c.getNextSibling())if(c instanceof Element)out.add((Element)c);return out;}
 static String local(Node n){return n.getLocalName()==null?n.getNodeName():n.getLocalName();}
 static List<Element> all(Node n,String name){List<Element> out=new ArrayList<>();if(n==null)return out;NodeList list=n instanceof Document?((Document)n).getElementsByTagNameNS("*",name):((Element)n).getElementsByTagNameNS("*",name);for(int i=0;i<list.getLength();i++)out.add((Element)list.item(i));return out;}
 static Element first(Node n,String name){List<Element> a=all(n,name);return a.isEmpty()?null:a.get(0);}
 static String attr(Element e,String name){if(e==null)return "";if(e.hasAttribute(name))return e.getAttribute(name);NamedNodeMap m=e.getAttributes();for(int i=0;i<m.getLength();i++)if(local(m.item(i)).equals(name))return m.item(i).getNodeValue();return "";}
 static int number(String s,int fallback){try{return Integer.parseInt(s);}catch(Exception e){return fallback;}}
 static String texts(Node n){StringBuilder s=new StringBuilder();for(Element t:all(n,"t"))s.append(t.getTextContent());return s.toString();}
 static String packagePath(String base,String target)throws IOException{if(target.contains(":")||target.contains("\\"))throw new IOException("无效文档关系路径");if(target.startsWith("/")){target=target.substring(1);base="";}Path p=Paths.get(base).resolve(target).normalize();if(p.startsWith(".."))throw new IOException("文档关系路径越界");return p.toString().replace('\\','/');}
 Map<String,String> rels(String part)throws Exception{int slash=part.lastIndexOf('/');String folder=slash<0?"":part.substring(0,slash+1);Document d=xml(folder+"_rels/"+part.substring(slash+1)+".rels");Map<String,String> out=new HashMap<>();for(Element e:all(d,"Relationship"))if(!"External".equalsIgnoreCase(attr(e,"TargetMode")))try{out.put(attr(e,"Id"),packagePath(folder,attr(e,"Target")));}catch(IOException ignored){}return out;}
 String image(String path)throws Exception{if(path==null)return "";String e=path.toLowerCase(Locale.ROOT),mime=e.endsWith(".png")?"image/png":e.endsWith(".jpg")||e.endsWith(".jpeg")?"image/jpeg":e.endsWith(".gif")?"image/gif":e.endsWith(".webp")?"image/webp":null;if(mime==null)return "";byte[] data=bytes(path);return data==null?"":"data:"+mime+";base64,"+Base64.getEncoder().encodeToString(data);}
 static String color(Element e){String v=attr(e,"val");return v.matches("[0-9a-fA-F]{6}")?"#"+v:"";}
 String wordNode(Element e,Map<String,String> rel)throws Exception{if(++wordDepth>64){wordDepth--;throw new IOException("文档嵌套过深");}try{String tag=local(e);StringBuilder out=new StringBuilder();if(tag.equals("p")){String style=attr(first(e,"pStyle"),"val"),wrap=style.matches("(?i)heading[1-6]")?"h"+style.substring(style.length()-1):style.equalsIgnoreCase("Title")?"h1":"p";out.append('<').append(wrap).append('>');for(Element c:children(e))out.append(wordNode(c,rel));out.append("</").append(wrap).append('>');}else if(tag.equals("tbl")||tag.equals("tr")||tag.equals("tc")){String wrap=tag.equals("tbl")?"table":tag.equals("tr")?"tr":"td";out.append('<').append(wrap);if(tag.equals("tc")){int span=Math.min(100,Math.max(1,number(attr(first(e,"gridSpan"),"val"),1)));out.append(" colspan=\"").append(span).append('"');}out.append('>');for(Element c:children(e))out.append(wordNode(c,rel));out.append("</").append(wrap).append('>');}else if(tag.equals("r")){Element props=first(e,"rPr");String col=color(first(props,"color"));int sz=number(attr(first(props,"sz"),"val"),0);String css=(first(props,"b")!=null?"font-weight:bold;":"")+(first(props,"i")!=null?"font-style:italic;":"")+(first(props,"u")!=null?"text-decoration:underline;":"")+(!col.isEmpty()?"color:"+col+";":"")+(sz>0?"font-size:"+Math.min(72,sz/2.0)+"pt;":"");out.append("<span style=\"").append(css).append("\">");for(Element c:children(e))if(!local(c).equals("rPr"))out.append(wordNode(c,rel));out.append("</span>");}else if(tag.equals("t"))out.append(esc(e.getTextContent()));else if(tag.equals("br")||tag.equals("cr"))out.append("<br>");else if(tag.equals("tab"))out.append("&emsp;");else if(tag.equals("blip")){String src=image(rel.get(attr(e,"embed")));if(!src.isEmpty())out.append("<img alt=\"文档图片\" src=\"").append(src).append("\">");}else if(!tag.endsWith("Pr"))for(Element c:children(e))out.append(wordNode(c,rel));return out.toString();}finally{wordDepth--;}}
 String word()throws Exception{Document d=xml("word/document.xml");if(d==null)throw new IOException("不是有效 DOCX 文档");Map<String,String> rel=rels("word/document.xml");StringBuilder out=new StringBuilder("<article class=word>");for(Element c:children(first(d,"body")))out.append(wordNode(c,rel));return out.append("</article>").toString();}
 static int column(String ref){int out=0;for(char c:ref.toUpperCase(Locale.ROOT).toCharArray()){if(c<'A'||c>'Z')break;out=out*26+c-'A'+1;if(out>16384)return out;}return out;}
 static String columnName(int n){StringBuilder s=new StringBuilder();while(n>0){n--;s.insert(0,(char)('A'+n%26));n/=26;}return s.toString();}
 String excel()throws Exception{Document book=xml("xl/workbook.xml");if(book==null)throw new IOException("不是有效 XLSX 工作簿");List<String> shared=new ArrayList<>();for(Element e:all(xml("xl/sharedStrings.xml"),"si"))shared.add(texts(e));Map<String,String> rel=rels("xl/workbook.xml");StringBuilder out=new StringBuilder("<nav class=sheets>");List<Element> sheets=all(book,"sheet");for(int n=0;n<Math.min(20,sheets.size());n++)out.append("<a href=#sheet-").append(n).append('>').append(esc(attr(sheets.get(n),"name"))).append("</a>");out.append("</nav><p class=notice>每表最多预览前 200 行、30 列；公式显示文件中的缓存结果，无缓存时显示公式，不重新计算。</p>");for(int n=0;n<Math.min(20,sheets.size());n++){Element sheet=sheets.get(n);Document d=xml(rel.getOrDefault(attr(sheet,"id"),"xl/worksheets/sheet"+(n+1)+".xml"));out.append("<section id=sheet-").append(n).append("><h2>").append(esc(attr(sheet,"name"))).append("</h2><div class=table-scroll><table><thead><tr><th></th>");int max=1;for(Element cell:all(d,"c"))max=Math.max(max,Math.min(30,column(attr(cell,"r"))));for(int col=1;col<=max;col++)out.append("<th>").append(columnName(col)).append("</th>");out.append("</tr></thead><tbody>");int visited=0;for(Element row:all(d,"row")){if(++visited>200)break;out.append("<tr><th>").append(esc(attr(row,"r"))).append("</th>");Map<Integer,Element> cells=new HashMap<>();for(Element c:children(row))if(local(c).equals("c"))cells.put(column(attr(c,"r")),c);for(int col=1;col<=max;col++){Element c=cells.get(col),v=first(c,"v"),f=first(c,"f");String value=v==null?"":v.getTextContent(),type=attr(c,"t");if(type.equals("s")){int at=number(value,-1);value=at>=0&&at<shared.size()?shared.get(at):"";}else if(type.equals("inlineStr"))value=texts(c);else if(type.equals("b"))value=value.equals("1")?"TRUE":"FALSE";if(value.isEmpty()&&f!=null)value="="+f.getTextContent();out.append("<td title=\"").append(esc(f==null?"":"="+f.getTextContent())).append("\">").append(esc(value)).append("</td>");}out.append("</tr>");}out.append("</tbody></table></div></section>");}if(sheets.size()>20)out.append("<p class=notice>仅展示前 20 个工作表。</p>");return out.toString();}
 static double emu(String s,double fallback){try{return Double.parseDouble(s)/9525.0;}catch(Exception e){return fallback;}}
 String ppt()throws Exception{Document presentation=xml("ppt/presentation.xml");if(presentation==null)throw new IOException("不是有效 PPTX 演示文稿");Map<String,String> slides=rels("ppt/presentation.xml");Element size=first(presentation,"sldSz");double width=emu(attr(size,"cx"),960),height=emu(attr(size,"cy"),540);if(width<=0||height<=0||width>10000||height>10000)throw new IOException("幻灯片尺寸无效");StringBuilder out=new StringBuilder("<nav class=sheets>");List<Element> ids=all(presentation,"sldId");for(int n=0;n<Math.min(100,ids.size());n++)out.append("<a href=#slide-").append(n).append('>').append(n+1).append("</a>");out.append("</nav>");for(int n=0;n<Math.min(100,ids.size());n++){Element id=ids.get(n);String rid=id.getAttributeNS("http://schemas.openxmlformats.org/officeDocument/2006/relationships","id");String part=slides.get(rid);if(part==null)continue;Document slide=xml(part);Map<String,String> rel=rels(part);String bg=color(first(first(slide,"bg"),"srgbClr"));out.append("<section id=slide-").append(n).append("><h2>第 ").append(n+1).append(" 页</h2><svg class=slide xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 ").append(width).append(' ').append(height).append("\"><rect width=\"100%\" height=\"100%\" fill=\"").append(bg.isEmpty()?"white":bg).append("\"/>");for(Element shape:children(first(slide,"spTree"))){String tag=local(shape);if(!tag.equals("sp")&&!tag.equals("pic"))continue;Element x=first(shape,"xfrm"),off=first(x,"off"),extent=first(x,"ext");double left=emu(attr(off,"x"),24),top=emu(attr(off,"y"),24),w=emu(attr(extent,"cx"),width-48),h=emu(attr(extent,"cy"),height-48);if(tag.equals("pic")){String src=image(rel.get(attr(first(shape,"blip"),"embed")));if(!src.isEmpty())out.append("<image x=\"").append(left).append("\" y=\"").append(top).append("\" width=\"").append(w).append("\" height=\"").append(h).append("\" href=\"").append(src).append("\"/>");continue;}out.append("<foreignObject x=\"").append(left).append("\" y=\"").append(top).append("\" width=\"").append(w).append("\" height=\"").append(h).append("\"><div xmlns=\"http://www.w3.org/1999/xhtml\" style=\"font:24px sans-serif;overflow:hidden;height:100%\">");for(Element p:all(shape,"p")){String align=attr(first(p,"pPr"),"algn");out.append("<p style=\"margin:0;text-align:").append(align.equals("ctr")?"center":align.equals("r")?"right":"left").append("\">");for(Element run:children(p)){if(local(run).equals("r")||local(run).equals("fld")){Element prop=first(run,"rPr");int sz=number(attr(prop,"sz"),2400);String col=color(first(prop,"srgbClr"));out.append("<span style=\"font-size:").append(Math.min(200,Math.max(6,sz/100.0*96/72))).append("px;").append(attr(prop,"b").equals("1")?"font-weight:bold;":"").append(!col.isEmpty()?"color:"+col+";":"").append("\">").append(esc(texts(run))).append("</span>");}else if(local(run).equals("br"))out.append("<br>");}out.append("</p>");}out.append("</div></foreignObject>");}out.append("</svg></section>");}return out.toString();}
 static String renderOffice(File f)throws Exception{try(DocumentPreview d=new DocumentPreview(f)){switch(ext(f)){case "docx":return d.word();case "xlsx":return d.excel();case "pptx":return d.ppt();default:throw new IOException("不支持的办公格式");}}}
 static String csv(String text,char separator){StringBuilder out=new StringBuilder("<p class=notice>最多预览 200 行、30 列。</p><div class=table-scroll><table><tbody><tr>"),cell=new StringBuilder();boolean quoted=false;int row=0,col=0;for(int i=0;i<=text.length();i++){char c=i==text.length()?'\n':text.charAt(i);if(c=='"'){if(quoted&&i+1<text.length()&&text.charAt(i+1)=='"'){cell.append('"');i++;}else if(quoted||cell.length()==0)quoted=!quoted;else cell.append(c);}else if(!quoted&&(c==separator||c=='\n'||c=='\r')){if(col<30)out.append("<td>").append(esc(cell.toString())).append("</td>");col++;cell.setLength(0);if(c=='\n'||c=='\r'){if(c=='\r'&&i+1<text.length()&&text.charAt(i+1)=='\n')i++;out.append("</tr>");if(++row>=200)break;col=0;if(i<text.length())out.append("<tr>");}}else cell.append(c);}return out.append("</tbody></table></div>").toString();}
 static String page(String content,boolean scripts){return "<!doctype html><html><head><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><meta http-equiv=Content-Security-Policy content=\"default-src 'none'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; font-src 'self'; script-src "+(scripts?"'self' 'unsafe-inline'":"'none'")+"; connect-src 'none'; frame-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'\"><style>body{margin:0;padding:18px;color:#252a32;background:#fff;font:15px/1.7 system-ui,sans-serif;overflow-wrap:anywhere}h1,h2,h3{line-height:1.4}h2{font-size:18px}img{max-width:100%;height:auto}table{border-collapse:collapse;font-size:13px}td,th{border:1px solid #dce1e7;padding:8px;min-width:64px;vertical-align:top;white-space:pre-wrap}th{background:#eef2f7;position:sticky;top:0}.table-scroll{overflow:auto;max-height:70vh}pre{white-space:pre-wrap;background:#f2f4f7;padding:14px;border-radius:8px}.word{max-width:800px;margin:auto}.word p{white-space:pre-wrap}.notice{font-size:12px;color:#627084}.slide{display:block;width:100%;border:1px solid #dce1e7;border-radius:6px;background:white}.sheets{display:flex;gap:8px;overflow:auto;position:sticky;top:0;background:white;padding:8px 0;z-index:2}.sheets a{padding:5px 10px;background:#edf2f8;border-radius:8px;white-space:nowrap;color:#234b7e;text-decoration:none}section{scroll-margin-top:64px}</style></head><body>"+content+"</body></html>";}
}
